 15	import { describe, it, expect, beforeEach, afterEach } from 'vitest';
 16	import { kspec, setupTempFixtures, cleanupTempDir, testUlid, createTempDir } from './helpers/cli';
 17	import * as fs from 'node:fs/promises';
 18	import * as path from 'node:path';
 19	
 20	describe('validate exit codes', () => {
 21	  let tempDir: string;
 22	
 23	  beforeEach(async () => {
 24	    tempDir = await setupTempFixtures();
 25	  });
 26	
 27	  afterEach(async () => {
 28	    await cleanupTempDir(tempDir);
 29	  });
 30	
 31	  // AC: @cli-exit-codes (exit 4 for validation errors)
 32	  describe('exit code 4 (VALIDATION_FAILED)', () => {
 33	    it('should exit 4 when schema errors are present', async () => {
 34	      // Create an invalid spec file with bad ULID
 35	      const specDir = path.join(tempDir, 'modules');
 36	      await fs.writeFile(
 37	        path.join(specDir, 'invalid.yaml'),
 38	        `
 39	items:
 40	  - _ulid: "not-a-valid-ulid"
 41	    title: "Bad Item"
 42	    type: feature
 43	`
 44	      );
 45	
 46	      // Update manifest to include the invalid file
 47	      const manifestPath = path.join(tempDir, 'kynetic.yaml');
 48	      const manifest = await fs.readFile(manifestPath, 'utf-8');
 49	      const updatedManifest = manifest.replace(
 50	        'includes:',
 51	        'includes:\n  - modules/invalid.yaml'
 52	      );
 53	      await fs.writeFile(manifestPath, updatedManifest);
 54	
 55	      const result = kspec('validate --schema', tempDir);
 56	      expect(result.exitCode).toBe(4);
 57	      expect(result.stderr + result.stdout).toContain('Schema errors');
 58	    });
 59	
 60	    it('should exit 4 when reference errors are present', async () => {
 61	      // Add a task with an invalid spec_ref
 62	      const tasksFile = path.join(tempDir, 'project.tasks.yaml');
 63	      const content = await fs.readFile(tasksFile, 'utf-8');
 64	      const newContent = content.replace(
 65	        'tasks:',
